// Builds public/vanshika_chanana_resume.pdf from content/site-data.js (same content as the website).
// Run locally: npm run resume   (then commit the PDF)
//
// resume/resume.html is GENERATED by this script. Edit content/site-data.js instead.
import { execFileSync } from "node:child_process";
import { existsSync, mkdirSync, statSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { education, experience, links, person, projects, resumeSummary, skills, volunteering } from "../content/site-data.js";

const esc = (s = "") => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const rich = (s) => esc(s).replace(/\*\*(.+?)\*\*/g, "<b>$1</b>");
const bullets = (pts = []) => (pts.length ? `<ul>${pts.map((p) => `<li>${rich(p)}</li>`).join("")}</ul>` : "");
const project = (p) => `
  <div class="proj"><b>${esc(p.name)}</b> <span class="stack">| ${esc(p.stack)}</span>${p.link ? ` | <a class="u" href="${p.link}">Live</a>` : ""}</div>
  ${bullets(p.points)}`;

const jobs = experience
  .map(
    (j) => `
<div class="job">
  <div class="row"><span class="role">${esc(j.role)}</span><span class="date">${esc(j.period)}</span></div>
  <div class="org">${esc(j.company)}${j.location ? ` &nbsp;|&nbsp; ${esc(j.location)}` : ""}</div>
  ${bullets(j.points)}
  ${(j.projects || []).map(project).join("")}
</div>`
  )
  .join("");

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<title>${esc(person.name)} - Resume</title>
<!-- GENERATED by scripts/build-resume.mjs from content/site-data.js. Do not edit by hand. -->
<style>
  @page { size: A4; margin: 11mm 12mm; }
  * { box-sizing: border-box; }
  body { margin: 0; font-family: Calibri, Carlito, "Segoe UI", Arial, sans-serif; font-size: 10pt; line-height: 1.32; color: #1a1a1a; }
  a { color: inherit; text-decoration: none; }
  a.u { color: #1f3a8a; text-decoration: underline; }
  header { text-align: center; margin-bottom: 6pt; }
  h1 { margin: 0; font-size: 20pt; letter-spacing: 0.5pt; color: #1f3a8a; }
  .title { font-size: 11pt; font-weight: 600; margin-top: 1pt; }
  .contact { margin-top: 2pt; color: #333; }
  .contact span + span::before { content: "  |  "; color: #888; white-space: pre; }
  h2 { font-size: 10.5pt; text-transform: uppercase; letter-spacing: 0.6pt; color: #1f3a8a; border-bottom: 1.2pt solid #1f3a8a; margin: 9pt 0 4pt; padding-bottom: 1pt; }
  .row { display: flex; justify-content: space-between; gap: 8pt; }
  .role { font-weight: 700; }
  .org { font-style: italic; color: #1f3a8a; }
  .date { font-weight: 700; white-space: nowrap; }
  .proj { margin: 4pt 0 1pt; }
  .proj .stack { font-style: italic; color: #555; font-size: 9.3pt; }
  ul { margin: 1pt 0 3pt; padding-left: 14pt; }
  li { margin: 0.8pt 0; }
  .job { margin-bottom: 5pt; }
  .skills p { margin: 1pt 0; }
  .avoid { break-inside: avoid; }
</style>
</head>
<body>
<header>
  <h1>${esc(person.name.toUpperCase())}</h1>
  <div class="title">Full-Stack &amp; AI Developer</div>
  <div class="contact">
    <span>${esc(person.location)}</span>
    <span><a class="u" href="mailto:${person.email}">${esc(person.email)}</a></span>
    <span><a class="u" href="${links.linkedin}">LinkedIn</a></span>
    <span><a class="u" href="${links.github}">GitHub</a></span>
    <span><a class="u" href="${person.siteUrl}">Portfolio</a></span>
  </div>
</header>

<h2>Summary</h2>
<p style="margin:0">${esc(resumeSummary)}</p>

<h2>Work Experience</h2>
${jobs}

<div class="avoid"><h2>Projects</h2>${projects.map(project).join("")}</div>

<div class="avoid skills"><h2>Technical Skills</h2>
${skills.map(([g, l]) => `<p><b>${esc(g)}:</b> ${esc(l)}</p>`).join("")}
</div>

<div class="avoid">
<h2>Education</h2>
${education.map((e) => `<div class="row"><span class="role">${esc(e.title)} — ${esc(e.place)}</span><span class="date">${esc(e.period)}</span></div>${e.detail ? `<div>${esc(e.detail)}</div>` : ""}`).join("")}
<h2>Volunteer Experience</h2>
${volunteering.map((v) => `<div class="row"><span class="role">${esc(v.title)} — ${esc(v.place)}</span><span class="date">${esc(v.period)}</span></div>${bullets([v.detail])}`).join("")}
</div>
</body>
</html>`;

mkdirSync("resume", { recursive: true });
const htmlPath = resolve("resume/resume.html");
writeFileSync(htmlPath, html);

const browser = [
  process.env.CHROME_PATH,
  "C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe",
  "C:/Program Files/Microsoft/Edge/Application/msedge.exe",
  "C:/Program Files/Google/Chrome/Application/chrome.exe",
  "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  "/usr/bin/google-chrome",
]
  .filter(Boolean)
  .find((p) => existsSync(p));
if (!browser) {
  console.error("No Edge/Chrome found. Set CHROME_PATH to your browser executable.");
  process.exit(1);
}

const out = resolve("public/vanshika_chanana_resume.pdf");
execFileSync(browser, ["--headless=new", "--disable-gpu", "--no-pdf-header-footer", `--print-to-pdf=${out}`, pathToFileURL(htmlPath).href], { stdio: "ignore" });
console.log(`✓ ${out} (${(statSync(out).size / 1024).toFixed(0)} KB)`);
